+// String returns the string representation of the label set.
+// It builds the result directly into a byte slice, avoiding the overhead
+// of a bytes.Buffer and intermediate allocations.
+func (ls Labels) String() string {
+	// Pre‑allocate a reasonable capacity to minimise reallocations.
+	// 64 bytes works well for typical small label sets.
+	b := make([]byte, 0, 64)
+	b = append(b, '{')
+	i := 0
+	ls.Range(func(l Label) {
+		if i > 0 {
+			b = append(b, ',', ' ')
+		}
+		b = append(b, l.Name...)
+		b = append(b, '=')
+		b = strconv.AppendQuote(b, l.Value)
+		i++
+	})
+	b = append(b, '}')
+	return string(b)
+}
