+func (b *Builder) Range(f func(l Label)) {
+	// Copy slices to avoid side‑effects from Set/Del during iteration.
+	origAdd := append([]Label(nil), b.add...)
+	origDel := append([]string(nil), b.del...)
+
+	// Build fast‑lookup maps for deletions and already‑added labels.
+	delMap := make(map[string]struct{}, len(origDel))
+	for _, d := range origDel {
+		delMap[d] = struct{}{}
+	}
+	addMap := make(map[string]struct{}, len(origAdd))
+	for _, a := range origAdd {
+		addMap[a.Name] = struct{}{}
+	}
+
+	// Emit base labels that are not deleted and not overridden.
+	b.base.Range(func(l Label) {
+		if _, ok := delMap[l.Name]; ok {
+			return
+		}
+		if _, ok := addMap[l.Name]; ok {
+			return
+		}
+		f(l)
+	})
+
+	// Emit added/overridden labels.
+	for _, a := range origAdd {
+		f(a)
+	}
+}

