+func (es Expressions) String() string {
+	// Build the expression list without intermediate allocations.
+	if len(es) == 0 {
+		return ""
+	}
+	var b strings.Builder
+	// Rough estimate: each expression string + ", " ≈ 2 extra bytes.
+	b.Grow(len(es) * 2)
+	for i, e := range es {
+		if i > 0 {
+			b.WriteString(", ")
+		}
+		b.WriteString(e.String())
+	}
+	return b.String()
+}
