+func (node *DurationExpr) String() string {
+	// Build the string representation manually to avoid excessive fmt calls.
+	var b strings.Builder
+	switch {
+	case node.Op == STEP:
+		b.WriteString("step()")
+	case node.Op == MIN:
+		b.WriteString("min(")
+		b.WriteString(node.LHS.String())
+		b.WriteString(", ")
+		b.WriteString(node.RHS.String())
+		b.WriteByte(')')
+	case node.Op == MAX:
+		b.WriteString("max(")
+		b.WriteString(node.LHS.String())
+		b.WriteString(", ")
+		b.WriteString(node.RHS.String())
+		b.WriteByte(')')
+	case node.LHS == nil:
+		// Unary duration expression.
+		switch node.Op {
+		case SUB:
+			b.WriteString(node.Op.String())
+			b.WriteString(node.RHS.String())
+		case ADD:
+			b.WriteString(node.RHS.String())
+		default:
+			panic(fmt.Sprintf("unexpected unary duration expression: %s", node.Op))
+		}
+	default:
+		b.WriteString(node.LHS.String())
+		b.WriteByte(' ')
+		b.WriteString(node.Op.String())
+		b.WriteByte(' ')
+		b.WriteString(node.RHS.String())
+	}
+	if node.Wrapped {
+		return "(" + b.String() + ")"
+	}
+	return b.String()
+}
