+func (node *MatrixSelector) String() string {
+	at, offset := node.atOffset()
+	// Work on a copy of the underlying VectorSelector.
+	vs := *node.VectorSelector.(*VectorSelector)
+	// Suppress duplicate @/offset rendering.
+	origOffset, origOffsetExpr, origTS, origSE := vs.OriginalOffset, vs.OriginalOffsetExpr, vs.Timestamp, vs.StartOrEnd
+	vs.OriginalOffset = 0
+	vs.OriginalOffsetExpr = nil
+	vs.Timestamp = nil
+	vs.StartOrEnd = 0
+
+	var rangeStr string
+	if node.RangeExpr != nil {
+		rangeStr = node.RangeExpr.String()
+	} else {
+		rangeStr = model.Duration(node.Range).String()
+	}
+
+	var b strings.Builder
+	b.WriteString(vs.String())
+	b.WriteByte('[')
+	b.WriteString(rangeStr)
+	b.WriteByte(']')
+	b.WriteString(at)
+	b.WriteString(offset)
+
+	// Restore original fields (preserve semantics for callers that may reuse the selector).
+	vs.OriginalOffset, vs.OriginalOffsetExpr, vs.Timestamp, vs.StartOrEnd = origOffset, origOffsetExpr, origTS, origSE
+
+	return b.String()
+}
