+func (node *SubqueryExpr) getSubqueryTimeSuffix() string {
+	var stepStr string
+	if node.Step != 0 {
+		stepStr = model.Duration(node.Step).String()
+	} else if node.StepExpr != nil {
+		stepStr = node.StepExpr.String()
+	}
+
+	var offsetStr string
+	switch {
+	case node.OriginalOffsetExpr != nil:
+		offsetStr = " offset " + node.OriginalOffsetExpr.String()
+	case node.OriginalOffset > 0:
+		offsetStr = " offset " + model.Duration(node.OriginalOffset).String()
+	case node.OriginalOffset < 0:
+		offsetStr = " offset -" + model.Duration(-node.OriginalOffset).String()
+	}
+
+	var atStr string
+	switch {
+	case node.Timestamp != nil:
+		atStr = fmt.Sprintf(" @ %.3f", float64(*node.Timestamp)/1000.0)
+	case node.StartOrEnd == START:
+		atStr = " @ start()"
+	case node.StartOrEnd == END:
+		atStr = " @ end()"
+	}
+
+	var rangeStr string
+	if node.RangeExpr != nil {
+		rangeStr = node.RangeExpr.String()
+	} else {
+		rangeStr = model.Duration(node.Range).String()
+	}
+
+	var b strings.Builder
+	b.WriteByte('[')
+	b.WriteString(rangeStr)
+	b.WriteByte(':')
+	b.WriteString(stepStr)
