+func fillLeftNaNsWithRightValuesOrMerge(tssLeft, tssRight []*timeseries) {
+	// Build a map from metric name string to the index of the right‑hand series.
+	// This allows O(1) lookup of a matching right series for a given left series.
+	rightIdxByName := make(map[string]int, len(tssRight))
+	for i, ts := range tssRight {
+		rightIdxByName[ts.MetricName.String()] = i
+	}
+
+	// Iterate over left series and fill NaNs or merge values.
+	for _, tsLeft := range tssLeft {
+		valuesLeft := tsLeft.Values
+		nameLeft := tsLeft.MetricName.String()
+		rightIdx, hasRight := rightIdxByName[nameLeft]
+
+		if hasRight {
+			// Right series with matching metric name exists – keep a reference
+			// to avoid repeated map lookups inside the inner loop.
+			tsRight := tssRight[rightIdx]
+			valuesRight := tsRight.Values
+			for i, v := range valuesLeft {
+				if math.IsNaN(v) {
