+	if len(tssRight) == 0 {
+		return
+	}
+
+	// Build a map from metric name to the list of right‑hand series with this name.
+	// This allows us to avoid scanning all right series for each left series.
+	rightByName := make(map[string][]*timeseries, len(tssRight))
+	for _, ts := range tssRight {
+		name := ts.MetricName.String()
+		rightByName[name] = append(rightByName[name], ts)
+	}
